ALTER TABLE plans ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE usage_prices ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE subscriptions ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE subscription_claims ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE invoices ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE invoice_lines ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE invoice_generation_keys ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE payment_attempts ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE payment_provider_events ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE refunds ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE billing_outbox_events ADD COLUMN deleted_at DATETIME(6) NULL, ADD COLUMN deleted_by TEXT NULL;

-- bounded-retention exception: billing_outbox_events keeps owner-supplied audit values and the shared cleaner may physically purge published rows.

CREATE TRIGGER plans_audit_bi BEFORE INSERT ON plans FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_at=NULL,NEW.deleted_by=NULL;
CREATE TRIGGER plans_audit_bu BEFORE UPDATE ON plans FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER plans_audit_bd BEFORE DELETE ON plans FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
